#include <array>
#include <functional>
#include <iostream>
#include <limits>
#include <queue>
#include <tuple>
#include <vector>
using namespace std;
int main() { int n, m, start, destination; cin >> n >> m >> start >> destination; vector<vector<pair<int, long long>>> graph(n + 1); while (m--) { int u, v; long long w; cin >> u >> v >> w; graph[u].push_back({v, w}); graph[v].push_back({u, w}); } const long long INF = numeric_limits<long long>::max() / 4; vector<array<long long, 2>> distance(n + 1, {INF, INF}); priority_queue<tuple<long long, int, int>, vector<tuple<long long, int, int>>, greater<>> queue; distance[start][0] = 0; queue.push({0, start, 0}); while (!queue.empty()) { auto [current, node, used] = queue.top(); queue.pop(); if (current != distance[node][used]) continue; for (auto [next, weight] : graph[node]) { if (current + weight < distance[next][used]) { distance[next][used] = current + weight; queue.push({distance[next][used], next, used}); } if (!used && current + weight / 2 < distance[next][1]) { distance[next][1] = current + weight / 2; queue.push({distance[next][1], next, 1}); } } } cout << min(distance[destination][0], distance[destination][1]) << '\n'; }
